import{_ as t,o,c as a,ae as n}from"./chunks/framework.vXWZTEWX.js";const g=JSON.parse('{"title":"ADR 024: Auth UX Enhancements (Remember Me & Interstitial) 🔐","description":"","frontmatter":{},"headers":[],"relativePath":"adr/024-auth-ux-enhancements.md","filePath":"adr/024-auth-ux-enhancements.md"}'),i={name:"adr/024-auth-ux-enhancements.md"};function r(s,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-024-auth-ux-enhancements-remember-me-interstitial-🔐" tabindex="-1">ADR 024: Auth UX Enhancements (Remember Me &amp; Interstitial) 🔐 <a class="header-anchor" href="#adr-024-auth-ux-enhancements-remember-me-interstitial-🔐" aria-label="Permalink to &quot;ADR 024: Auth UX Enhancements (Remember Me &amp; Interstitial) 🔐&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>While the application had functional authentication, the user experience was friction-heavy. Users had to re-enter credentials every time they closed the tab (session-only storage default), and there was no visual indication of a valid session when returning to the login page (it just showed an empty form or redirected abruptly). Additionally, the &quot;Forgot Password&quot; flow was disconnected.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have implemented a set of UX refinements to align with &quot;Enterprise&quot; expectations for authentication:</p><h3 id="_1-dual-storage-strategy-remember-me" tabindex="-1">1. Dual-Storage Strategy (Remember Me) <a class="header-anchor" href="#_1-dual-storage-strategy-remember-me" aria-label="Permalink to &quot;1. Dual-Storage Strategy (Remember Me)&quot;">​</a></h3><p>We modified <code>AuthContext</code> to support both <code>localStorage</code> and <code>sessionStorage</code>.</p><ul><li><strong>Default</strong>: <code>sessionStorage</code> (Session persistence only).</li><li><strong>Remember Me</strong>: <code>localStorage</code> (Long-term persistence).</li><li><strong>Implementation</strong>: The <code>login()</code> method now accepts a <code>rememberMe</code> boolean. <code>AuthContext</code> initialization logic checks <code>localStorage</code> first, then <code>sessionStorage</code>.</li></ul><h3 id="_2-welcome-back-interstitial" tabindex="-1">2. &quot;Welcome Back&quot; Interstitial <a class="header-anchor" href="#_2-welcome-back-interstitial" aria-label="Permalink to &quot;2. &quot;Welcome Back&quot; Interstitial&quot;">​</a></h3><p>Instead of confusingly redirecting authenticated users or showing them an empty login form, we introduced a <strong>&quot;Welcome Back&quot;</strong> state in <code>LoginForm</code>.</p><ul><li><strong>UI</strong>: Displays the user&#39;s name/email and offers two explicit choices: <ol><li><strong>Continue to Dashboard</strong> (Primary Action)</li><li><strong>Switch User</strong> (Secondary Action - triggers Logout)</li></ol></li><li><strong>Benefit</strong>: Reduces friction for returning users while maintaining clarity and security.</li></ul><h3 id="_3-forgot-password-integration" tabindex="-1">3. Forgot Password Integration <a class="header-anchor" href="#_3-forgot-password-integration" aria-label="Permalink to &quot;3. Forgot Password Integration&quot;">​</a></h3><ul><li>Added a dedicated <code>/forgot-password</code> route and form.</li><li>Linked prominently from the Login screen.</li><li>Currently mocks the email sending (backend endpoint returns success) to complete the UX loop.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="_4-httponly-cookies-security-hardening-🛡️" tabindex="-1">4. HttpOnly Cookies (Security Hardening) 🛡️ <a class="header-anchor" href="#_4-httponly-cookies-security-hardening-🛡️" aria-label="Permalink to &quot;4. HttpOnly Cookies (Security Hardening) 🛡️&quot;">​</a></h3><p>We migrated from <code>localStorage</code> to <strong>HttpOnly Cookies</strong> for token storage.</p><ul><li><strong>Why</strong>: Prevents XSS attacks. Even if JS is compromised, the attacker cannot read the <code>httpOnly</code> cookie.</li><li><strong>Implementation</strong>: <ul><li>Backend: Uses <code>cookie-parser</code>. <code>AuthController</code> sets an <code>httpOnly; secure; sameSite</code> cookie.</li><li>Frontend: <code>credentials: &#39;include&#39;</code> in all <code>fetch</code> requests.</li><li><strong>Persistence</strong>: &quot;Remember Me&quot; toggles the cookie&#39;s <code>Max-Age</code>. Checked = 30 days; Unchecked = Session Cookie.</li></ul></li></ul><h2 id="consequences-1" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-1" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Security</strong>: Significantly reduces XSS impact on auth tokens.</li><li><strong>UX</strong>: &quot;Remember Me&quot; works seamlessly without exposing tokens.</li><li><strong>User Clarity</strong>: &quot;Welcome Back&quot; flow remains consistent.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Dev Complexity</strong>: Requires handling Cross-Origin credentials (CORS) carefully.</li><li><strong>Testing</strong>: E2E tests need to handle cookies rather than just setting localStorage.</li></ul><h2 id="alternatives-considered" tabindex="-1">alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;alternatives Considered&quot;">​</a></h2><h3 id="httponly-cookies-the-gold-standard" tabindex="-1">HttpOnly Cookies (The Gold Standard) <a class="header-anchor" href="#httponly-cookies-the-gold-standard" aria-label="Permalink to &quot;HttpOnly Cookies (The Gold Standard)&quot;">​</a></h3><p>Instead of storing tokens in <code>localStorage</code> (accessible by JS), the backend would set a <code>secure; httpOnly</code> cookie.</p><ul><li><strong>Pros</strong>: Immune to XSS token theft.</li><li><strong>Cons</strong>: Requires CSRF protection (Double Submit Cookie or SameSite settings) and backend state changes.</li><li><strong>Decision</strong>: For Phase 9, we chose <code>localStorage</code> for simplicity and statelessness, but acknowledge Cookies as the next security hardening step.</li></ul>',29)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
